  1	#!/usr/bin/env node
  2	/**
  3	 * Install (or update) the Zimmermann Environment Template into one target environment.
  4	 *
  5	 * Replaces the old runMigrations.mjs promotion flow. There is no more hand-rolled
  6	 * '_migrationHistory' content type or detectDrift.mjs — Contentful tracks each
  7	 * environment's install status/version natively via environmentTemplateInstallation,
  8	 * and cross-environment content-type drift can't happen the way it used to since every
  9	 * environment installs from the same versioned template.
 10	 *
 11	 * Usage:
 12	 *   npm run sync:contentful                            # author the template first (buildTemplate.js)
 13	 *   npm run install:contentful -- --target dev
 14	 *   npm run install:contentful -- --target sit --dry-run
 15	 *
 16	 * If validation reports a content type that already exists in the target environment
 17	 * but isn't managed by this template (e.g. one created by the old sync.js pipeline
 18	 * before this template-based approach existed), the install is refused by Contentful.
 19	 * Adopt it into the template explicitly rather than deleting it first:
 20	 *   npm run install:contentful -- --target dev --takeover shoppableImage,otherType
 21	 *
 22	 * Promotion order: dev → test → sit → staging → uat → master (via production alias)
 23	 */
 24	
 25	import { checkEnv, createClient, log } from './_shared.mjs';
 26	
 27	const args = process.argv.slice(2);
 28	const getArg = (flag) => {
 29	  const i = args.indexOf(flag);
 30	  return i !== -1 ? args[i + 1] : null;
 31	};
 32	
 33	const TARGET = getArg('--target');
 34	const DRY_RUN = args.includes('--dry-run');
 35	const FORCE = args.includes('--force');
 36	const DELETE_DELETED_FIELDS = args.includes('--delete-deleted-fields');
 37	const TAKEOVER_IDS = (getArg('--takeover') ?? '')
 38	  .split(',')
 39	  .map((s) => s.trim())
 40	  .filter(Boolean);
 41	
 42	if (!TARGET) {
 43	  log.error('--target <environmentId> is required.');
 44	  console.error('  Example: npm run install:contentful -- --target dev\n');
 45	  console.error('  Promotion order: dev → test → sit → staging → uat → master\n');
 46	  process.exit(1);
 47	}
 48	
 49	// Must match TEMPLATE_NAME in ../buildTemplate.js — the template is looked up by name,
 50	// not a stored ID, so the two files just need to agree on the literal.
 51	const TEMPLATE_NAME = 'Zimmermann Content Model';
 52	
 53	const TERMINAL_STATUSES = new Set(['succeeded', 'failed', 'disconnected']);
 54	
 55	async function pollInstallation(
 56	  client,
 57	  { organizationId, spaceId, environmentId, environmentTemplateId },
 58	  timeoutMs = 120_000,
 59	) {
 60	  const deadline = Date.now() + timeoutMs;
 61	  while (Date.now() < deadline) {
 62	    const { items } = await client.environmentTemplateInstallation.getForEnvironment({
 63	      spaceId,
 64	      environmentId,
 65	      environmentTemplateId,
 66	      limit: 1,
 67	    });
 68	    const [latest] = items;
 69	    if (latest && TERMINAL_STATUSES.has(latest.sys.status)) return latest;
 70	    await new Promise((r) => setTimeout(r, 3_000));
 71	    process.stdout.write('.');
 72	  }
 73	  throw new Error(`Installation into '${environmentId}' did not reach a terminal status within ${timeoutMs / 1000}s`);
 74	}
 75	
 76	async function main() {
 77	  checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_ORGANIZATION_ID', 'CONTENTFUL_SPACE_ID']);
 78	
 79	  const organizationId = process.env.CONTENTFUL_ORGANIZATION_ID;
 80	  const spaceId = process.env.CONTENTFUL_SPACE_ID;
 81	
 82	  const client = createClient();
 83	
 84	  const { items: templates } = await client.environmentTemplate.getMany({ organizationId, query: { limit: 100 } });
 85	  const template = templates.find((t) => t.name === TEMPLATE_NAME);
 86	
 87	  if (!template) {
 88	    log.error(`No EnvironmentTemplate named "${TEMPLATE_NAME}" found in organization '${organizationId}'.`);
 89	    console.error('  Run `npm run build:contentful` first.\n');
 90	    process.exit(1);
 91	  }
 92	
 93	  log.section(`Install → '${TARGET}'`);
 94	  console.log(`  Template: "${TEMPLATE_NAME}" (version ${template.sys.version})`);
 95	
 96	  log.info('Validating...');
 97	  const validation = await client.environmentTemplate.validate(
 98	    { spaceId, environmentId: TARGET, environmentTemplateId: template.sys.id, version: template.sys.version },
 99	    {},
100	  );
101	
102	  const conflictingIds = (validation.items ?? [])
103	    .filter((f) => f.message === 'conflictingContentTypes')
104	    .map((f) => f.details?.contentTypeId)
105	    .filter(Boolean);
106	
107	  if (validation.items?.length) {
108	    log.warn('Validation findings:');
109	    for (const finding of validation.items) {
110	      console.log(`    ${finding.message}${finding.details?.message ? ` — ${finding.details.message}` : ''}`);
111	    }
112	    if (conflictingIds.length && !TAKEOVER_IDS.length) {
113	      console.log(
114	        `\n  These content types already exist in '${TARGET}' but aren't managed by this template.\n` +
115	          `  Re-run with --takeover ${conflictingIds.join(',')} to adopt them, once you've confirmed that's intended.\n`,
116	      );
117	    }
118	  } else {
119	    log.success('No validation findings.');
120	  }
121	
122	
123	  // A finding is resolved only if it is a conflict this run explicitly adopts. The gate used to
124	  // test `!(conflictingIds.length && TAKEOVER_IDS.length)`, which asked "is there at least one
125	  // conflict and at least one takeover?" rather than "is every finding accounted for" — so any
126	  // single --takeover opened the gate for every *other* finding too, including conflicts it
127	  // didn't name and findings of unrelated classes. `message` is an open string in the SDK's
128	  // types, so the set of classes isn't bounded by the one handled here.
129	  const takeoverSet = new Set(TAKEOVER_IDS);
130	  const unresolved = (validation.items ?? []).filter(
131	    (f) => !(f.message === 'conflictingContentTypes' && takeoverSet.has(f.details?.contentTypeId)),
132	  );
133	
134	  const unknownTakeovers = TAKEOVER_IDS.filter((id) => !conflictingIds.includes(id));
135	  if (unknownTakeovers.length) {
136	    log.warn(
137	      `--takeover names ${unknownTakeovers.join(', ')}, which ${unknownTakeovers.length === 1 ? 'is' : 'are'} not in the conflict list — typo? Adopting nothing for ${unknownTakeovers.length === 1 ? 'it' : 'them'}.`,
138	    );
139	  }
140	
141	  if (DRY_RUN) {
142	    // Reported after the unresolved set is computed, not before it. Previously dry-run returned
143	    // ahead of the gate and always printed "Would install", which made it useless as a pre-flight
144	    // for the one check it most needed to preview. Still exits 0 — a dry run reports, it doesn't
145	    // adjudicate.
146	    if (unresolved.length && !FORCE) {
147	      log.warn(
148	        `[dry-run] Would REFUSE to install into '${TARGET}' — ${unresolved.length} unresolved validation finding(s).`,
149	      );
150	    } else {
151	      log.info(`[dry-run] Would install template version ${template.sys.version} into '${TARGET}'.`);
152	    }
153	    return;
154	  }
155	
156	  if (unresolved.length && !FORCE) {
157	    log.error(
158	      `Refusing to install into '${TARGET}' — ${unresolved.length} unresolved validation finding(s). Pass --force to override.`,
159	    );
160	    for (const finding of unresolved) {
161	      console.log(`    ${finding.message}${finding.details?.contentTypeId ? ` (${finding.details.contentTypeId})` : ''}`);
162	    }
163	    process.exit(1);
164	  }
165	
166	  // Send only ids Contentful actually reported as conflicting. The warning above tells the
167	  // operator that unknown ids adopt nothing; this is what makes that true rather than merely
168	  // stated — otherwise a typo'd id is still POSTed as a ContentType link to adopt.
169	  const adoptableIds = TAKEOVER_IDS.filter((id) => conflictingIds.includes(id));
170	  const takeover = adoptableIds.length
171	    ? { items: adoptableIds.map((id) => ({ sys: { type: 'Link', linkType: 'ContentType', id } })) }
172	    : undefined;
173	
174	  log.info(`Installing into '${TARGET}'...`);
175	  await client.environmentTemplate.install(
176	    { spaceId, environmentId: TARGET, environmentTemplateId: template.sys.id },
177	    { version: template.sys.version, deleteDeletedFields: DELETE_DELETED_FIELDS, takeover },
178	  );
179	
180	  const result = await pollInstallation(client, {
181	    organizationId,
182	    spaceId,
183	    environmentId: TARGET,
184	    environmentTemplateId: template.sys.id,
185	  });
186	
187	  if (result.sys.status === 'succeeded') {
188	    console.log(`\n  ✅  Installed template version ${template.sys.version} into '${TARGET}'.\n`);
189	  } else {
190	    log.error(`Installation into '${TARGET}' ended with status '${result.sys.status}'.`);
191	    if (result.sys.errors) console.error(JSON.stringify(result.sys.errors, null, 2));
192	    process.exit(1);
193	  }
194	}
195	
196	main().catch((err) => {
197	  log.error(err.message ?? err);
198	  process.exit(1);
199	});

