     1	#!/usr/bin/env node
     2	/**
     3	 * Seed the 11 canonical `region` entries into one target environment.
     4	 *
     5	 * Environment Templates (buildTemplate.js / installTemplate.mjs) cover content-TYPE
     6	 * schema only — entries are a separate concern and have to be seeded per environment
     7	 * after that environment's `region` content type exists (i.e. after installTemplate.mjs
     8	 * has run against it).
     9	 *
    10	 * Idempotent — uses deterministic entry IDs (`region-<siteId>`) so re-running is safe.
    11	 *
    12	 * Usage:
    13	 *   npm run seed:contentful-regions -- --target dev
    14	 */
    15	
    16	import { checkEnv, createClient, log } from './_shared.mjs';
    17	
    18	const args = process.argv.slice(2);
    19	const getArg = (flag) => {
    20	  const i = args.indexOf(flag);
    21	  return i !== -1 ? args[i + 1] : null;
    22	};
    23	
    24	const TARGET = getArg('--target');
    25	
    26	if (!TARGET) {
    27	  log.error('--target <environmentId> is required.');
    28	  console.error('  Example: npm run seed:contentful-regions -- --target dev\n');
    29	  process.exit(1);
    30	}
    31	
    32	// Space default locale — matches DEFAULT_LOCALE in overrides/app/config/contentfulMapping.ts.
    33	const DEFAULT_LOCALE = 'en';
    34	
    35	// Source: overrides/app/config/contentfulMapping.generated.ts's SITE_LOCALES keys,
    36	// copied 2026-08-23. Re-check that file if this list needs to change — it's
    37	// autogenerated from live SFCC site config via `npm run sync:regional-config` and this
    38	// static copy can drift from it.
    39	const REGION_SEEDS = [
    40	  { siteId: 'ZimmermannAU', label: 'Australia', locale: 'en' },
    41	  { siteId: 'ZimmermannUS', label: 'US Domestic', locale: 'en-US' },
    42	  { siteId: 'ZimmermannUSIntl', label: 'US International', locale: 'en-CA' },
    43	  { siteId: 'ZimmermannUK', label: 'United Kingdom', locale: 'en-GB' },
    44	  { siteId: 'ZimmermannEUen', label: 'Europe (English)', locale: 'en-GB' },
    45	  { siteId: 'ZimmermannEUfr', label: 'Europe (French)', locale: 'fr' },
    46	  { siteId: 'ZimmermannEUit', label: 'Europe (Italian)', locale: 'it' },
    47	  { siteId: 'ZimmermannEUes', label: 'Europe (Spanish)', locale: 'es' },
    48	  { siteId: 'ZimmermannEUIntl', label: 'Europe International', locale: 'en-CH' },
    49	  { siteId: 'ZimmermannHK', label: 'Hong Kong', locale: 'en-HK' },
    50	  { siteId: 'ZimmermannME', label: 'Middle East', locale: 'en-AE' },
    51	];
    52	
    53	async function upsertEntry(client, environmentId, contentTypeId, entryId, fields) {
    54	  const localizedFields = Object.fromEntries(
    55	    Object.entries(fields).map(([fieldId, value]) => [fieldId, { [DEFAULT_LOCALE]: value }]),
    56	  );
    57	
    58	  let exists = true;
    59	  try {
    60	    await client.entry.get({ environmentId, entryId });
    61	  } catch (err) {
    62	    if (err.name !== 'NotFound') throw err;
    63	    exists = false;
    64	  }
    65	
    66	  if (exists) {
    67	    log.skip(`region-${fields.siteId} already exists`);
    68	    return;
    69	  }
    70	
    71	  const entry = await client.entry.createWithId({ environmentId, entryId, contentTypeId }, { fields: localizedFields });
    72	  await client.entry.publish({ environmentId, entryId }, entry);
    73	  log.success(`Seeded region-${fields.siteId}`);
    74	}
    75	
    76	async function main() {
    77	  checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);
    78	
    79	  const client = createClient();
    80	
    81	  log.section(`Seed regions → '${TARGET}'`);
    82	
    83	  for (const seed of REGION_SEEDS) {
    84	    await upsertEntry(client, TARGET, 'region', `region-${seed.siteId}`, seed);
    85	  }
    86	
    87	  console.log(`\n  ✅  Region entries up to date in '${TARGET}'.\n`);
    88	}
    89	
    90	main().catch((err) => {
    91	  log.error(err.message ?? err);
    92	  process.exit(1);
    93	});

